// ComboSystem.cs — Queue + Dictionary + evento tipado
using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class ComboSystem : MonoBehaviour
{
    // Cualquier sistema puede escuchar combos ejecutados
    public event Action<string> OnComboExecuted;

    [SerializeField] private float comboWindow = 0.5f; // segundos entre inputs

    // Historial circular de inputs recientes con timestamp
    private readonly Queue<(string input, float time)> _inputBuffer
        = new Queue<(string, float)>();

    // Combos registrados: secuencia → nombre del combo
    private readonly Dictionary<string[], string> _combos
        = new Dictionary<string[], string>(new SequenceComparer());

    private void Awake()
    {
        // Los combos se registran aquí o desde un ScriptableObject externo
        _combos[new[] { "Attack", "Attack", "Attack" }] = "TripleAttack";
        _combos[new[] { "Attack", "Special" }]           = "FinisherMove";
        _combos[new[] { "Jump", "Attack", "Special" }]   = "AerialFinisher";
    }

    private void Update()
    {
        // Limpiar inputs expirados
        while (_inputBuffer.Count > 0 &&
               Time.time - _inputBuffer.Peek().time > comboWindow)
            _inputBuffer.Dequeue();

        // Registrar input del frame
        if (Input.GetButtonDown("Attack"))  RecordInput("Attack");
        if (Input.GetButtonDown("Special")) RecordInput("Special");
        if (Input.GetButtonDown("Jump"))    RecordInput("Jump");
    }

    private void RecordInput(string inputName)
    {
        _inputBuffer.Enqueue((inputName, Time.time));
        CheckCombos();
    }

    private void CheckCombos()
    {
        string[] current = _inputBuffer.Select(e => e.input).ToArray();

        foreach (var kvp in _combos)
        {
            // Verificar si el buffer termina con la secuencia del combo
            if (current.Length >= kvp.Key.Length &&
                current.Skip(current.Length - kvp.Key.Length)
                       .SequenceEqual(kvp.Key))
            {
                OnComboExecuted?.Invoke(kvp.Value);
                _inputBuffer.Clear();
                return;
            }
        }
    }
}

// IComparer necesario para usar string[] como clave de Dictionary
public class SequenceComparer : IEqualityComparer<string[]>
{
    public bool Equals(string[] x, string[] y)   => x.SequenceEqual(y);
    public int  GetHashCode(string[] obj)          => obj.Aggregate(17, (h, s) => h * 31 + s.GetHashCode());
}

