// EventBus.cs — bus genérico estático, sin dependencias externas
using System;
using System.Collections.Generic;

public static class EventBus<T>
{
    private static readonly Dictionary<Type, Action<T>> _handlers
        = new Dictionary<Type, Action<T>>();

    public static void Subscribe(Action<T> handler)
    {
        Type key = typeof(T);
        if (!_handlers.ContainsKey(key)) _handlers[key] = null;
        _handlers[key] += handler;
    }

    public static void Unsubscribe(Action<T> handler)
    {
        Type key = typeof(T);
        if (_handlers.ContainsKey(key)) _handlers[key] -= handler;
    }

    public static void Publish(T eventData)
    {
        Type key = typeof(T);
        if (_handlers.TryGetValue(key, out var action))
            action?.Invoke(eventData);
    }
}

